package android.provider;import android.content.ContentResolver;import android.net.Uri;public final class Settings{public static boolean canDrawOverlays(android.content.Context c){return "1".equals(c.getContentResolver().settings.get("overlay_allowed"));}public static final String ACTION_MANAGE_OVERLAY_PERMISSION="overlay_permission";public static final String ACTION_ACCESSIBILITY_SETTINGS="accessibility",ACTION_REQUEST_IGNORE_BATTERY_OPTIMIZATIONS="ignore_battery",ACTION_APPLICATION_DETAILS_SETTINGS="app_details";public static class Secure{public static final String ENABLED_ACCESSIBILITY_SERVICES="enabled_accessibility_services",ACCESSIBILITY_ENABLED="accessibility_enabled";public static String getString(ContentResolver r,String key){return r.settings.get(key);}public static boolean putString(ContentResolver r,String k,String v){r.settings.put(k,v);return true;}public static boolean putInt(ContentResolver r,String k,int v){return putString(r,k,Integer.toString(v));}public static Uri getUriFor(String key){return Uri.parse(key);}}}